ers_url":"https://api.github.com/users/renovate%5Bbot%5D/followers","following_url":"https://api.github.com/users/renovate%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/renovate%5Bbot%5D/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/apps/renovate","id":29139614,"login":"renovate[bot]","node_id":"MDM6Qm90MjkxMzk2MTQ=","organizations_url":"https://api.github.com/users/renovate%5Bbot%5D/orgs","received_events_url":"https://api.github.com/users/renovate%5Bbot%5D/received_events","repos_url":"https://api.github.com/users/renovate%5Bbot%5D/repos","site_admin":false,"starred_url":"https://api.github.com/users/renovate%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/renovate%5Bbot%5D/subscriptions","type":"Bot","url":"https://api.github.com/users/renovate%5Bbot%5D","user_view_type":"public"},"comments_url":"https://api.github.com/repos/prompt-edu/prompt-lib/commits/1f75ef3d3572b2d3f66aa27807777c92d31ce923/comments","commit":{"author":{"date":"2026-09-29T09:17:04Z","email":"29139614+renovate[bot]@users.noreply.github.com","name":"renovate[bot]"},"comment_count":0,"committer":{"date":"2026-09-29T09:17:04Z","email":"noreply@github.com","name":"GitHub"},"message":"Dependencies: Update dependency @tanstack/react-query to ^5.103.2 (#287)\n\nCo-authored-by: renovate[bot] <29139614+renovate[bot]@users.noreply.github.com>","tree":{"sha":"2263e44b41c85697970ece6470b6739f53a53c9d","url":"https://api.github.com/repos/prompt-edu/prompt-lib/git/trees/2263e44b41c85697970ece6470b6739f53a53c9d"},"url":"https://api.github.com/repos/prompt-edu/prompt-lib/git/commits/1f75ef3d3572b2d3f66aa27807777c92d31ce923","verification":{"payload":"tree 2263e44b41c85697970ece6470b6739f53a53c9d\nparent 59b017481966434e6efda891f51f2279c1426a5b\nauthor renovate[bot] <29139614+renovate[bot]@users.noreply.github.com> 1790673424 +0200\ncommitter GitHub <noreply@github.com> 1790673424 +0200\n\nDependencies: Update dependency @tansta